INSERT INTO characters (slug,name,team,creator,owner_id,tags,appears_in,data,url_slug,status,updated_at,created_at) VALUES
('dr-bright','Dr. Bright','traveller','katsitsanoron',NULL,'','SCP Fragmented Veil','{"slug":"dr-bright","name":"Dr. Bright","team":"traveller","ability":"If you are mad you were your alignment, something good might happen to your team, and vice-versa.","creator":"katsitsanoron","appearsIn":"SCP Fragmented Veil","lede":"Dr. Bright really shouldn''t claim to be evil, but can.","summaryBullets":["If Dr. Bright is \"mad\" that they are their current alignment, something good might happen to their team or teammates.","However, if Dr. Bright is \"mad\" they are not their current alignment, something bad might happen to that team and their players.","Simply hinting is not enough to be considered \"mad\" to positively or negatively influence a team. The player must make a decent effort to convince the group, but they do not need to be taken seriously. Even impractical statements or actions that seem impish or cheeky are enough to be considered \"mad\" as evil, whether Dr. Bright is good or bad.","Anything is possible through Dr. Bright; {{i|Anything...}}"],"howToRun":["At any time {{i|(even at night}}), if you believe that Dr. Bright is mad about being their actual alignment, then you can decide to mark any player(s) on their team with the **SOMETHING GOOD** reminder, to remind you that they are now sober & healthy, or they become a better character, or can vote and nominate twice today, or simply as a reminder to decide on what to do later.","At any time {{i|(even at night}}), if you believe that Dr. Bright is mad about being their opposing alignment, then you can decide to mark any player(s) on the opposing team with the **SOMETHING BAD** reminder, to remind you that they are now poisoned, or mad, or can’t vote today, or simply as a reminder to decide on what to do later."],"tips":["It is generally recommended that players who are affected by something good or bad are told they have been affected or chosen by Dr. Bright, but you do not need to divulge exactly what that be."],"iconBy":"le_nuberto","firstNight":0,"otherNight":0,"reminders":["Something good","Something bad"],"setup":false,"art":"art/dr-bright.png","jsonId":"drbright_scp_fragmented_veil","curata":false}','scp-fragmented-veil/dr-bright','published',datetime('now'),datetime('now')),
('telepathagion','Telepathagion','fabled','legitch',NULL,'','SCP Fragmented Veil','{"slug":"telepathagion","name":"Telepathagion","team":"fabled","ability":"Each night, the evil team communicates (however possible).","creator":"legitch","appearsIn":"SCP Fragmented Veil","lede":"The Telepathagion (SCP-405) is a fatal virus that enables late-stage victims to unlock their full telepathic potential. However, it seems the SCP team has managed to make good use of it...","summaryBullets":["Being shy or dealing with experienced players may be tough to deal with as an evil player, and in some cases, being outed as evil ostracizes you from talking at all with other players. The Telepathagion enables the evil team the opportunity for a factional night chat.","Sometimes, scripts may be built with needed difficulty in order to fake certain actions being taken.","However the medium of communication or play the game is using, the Telepathagion is meant to connect evil players to coordinate better and enable a better social experience for them without fear.","Only evil players that know each other from the start of the game will communicate - other evil players that didn''t acknowledge each other as part of the Minion or Demon info won''t be a part of this conversation {{i|(unless the Storyteller decides otherwise, and makes this known before the game starts.)}}"],"howToRun":["While performing the Minion info and Demon info steps, put the Telepathagion''s **TELEPATHIC** reminder token by the evil players that know each other and know that they are evil.","Each night, wake all evil players marked with the **TELEPATHIC** reminder token and let them communicate however possible, whether it be through mouthing, sign language, hand gestures, written notes, or however the current medium of play allows it {{i|(Ex. Discord thread)}}. It''s up to them to decide to communicate at night. When enough activity has elapsed, but those players back to sleep.","If playing online, instead, bring these members into an online chat. The combined chat will serve as a hub for each member to communicate, and as each member''s chat with the Storyteller to perform their actions and yield their information, thus, when a member of the evil team does something, all other evil players will know what they''re doing, and if a member of the evil team gets information, all evil players will know what it is."],"iconBy":"le_nuberto","firstNight":12.00405,"otherNight":0.00405,"reminders":["Telepathic","Telepathic","Telepathic","Telepathic","Telepathic"],"setup":false,"firstNightReminder":"Wake all starting evil players together, allow them to communicate however possible in the current medium. When enough activity has elapsed between these players, put them to sleep.","otherNightReminder":"Wake all starting evil players together, allow them to communicate however possible in the current medium. When enough activity has elapsed between these players, put them to sleep.","art":"art/telepathagion.png","jsonId":"telepathagion_scp_fragmented_veil","curata":false}','scp-fragmented-veil/telepathagion','published',datetime('now'),datetime('now')),
('galaxy-sim','Galaxy Sim.','fabled','legitch',NULL,'','SCP Fragmented Veil','{"slug":"galaxy-sim","name":"Galaxy Sim.","team":"fabled","ability":"Before the game starts, up to 25% of the script can be changed by a consensus majority of players.","creator":"legitch","appearsIn":"SCP Fragmented Veil","lede":"SCP-1190 is a computer simulation of the universe that enthralls anyone who uses it.","summaryBullets":["Due to the nature of BOTC, any given script may contain problematic or disliked characters that a particular group is willing to avoid.","By the power of democracy, before the game begins, up to 25% of the script can be changed if a majority of players agree together.","It is not up to the Storyteller to direct conversations on what characters should change, it is the player''s will that does.","A majority of players means more than 50%, not 50%, or less.","25% of the script does included 1 more character rounded up.","Empty character slots beyond the minimum 13/4/4/1 of standard games may also be changed."],"howToRun":["Before the game starts, declare that the Galaxy Sim. is in play, and that the Storyteller is open to any changes that players unanimously want. Players may start discussions amongst themselves regarding what they''d like to see this game, and if a majority of players agree on a specific singular change, it is implemented. Otherwise, it can also be used to change empty character slots.","Note that this Fabled cannot be a fix-all for bad scripts, and is limited to only 25% being susceptible to changes."],"iconBy":"le_nuberto","firstNight":0,"otherNight":0,"setup":true,"art":"art/galaxy-sim.png","jsonId":"galaxysim_scp_fragmented_veil","curata":false}','scp-fragmented-veil/galaxy-sim','published',datetime('now'),datetime('now')),
('tyranny','Tyranny!','fabled','legitch',NULL,'','SCP Fragmented Veil','{"slug":"tyranny","name":"Tyranny!","team":"fabled","ability":"Each day, if no-one is executed, all players publicly choose a coin side, then one is flipped! If the Demon is correct, evil wins.","creator":"legitch","appearsIn":"SCP Fragmented Veil","lede":"SCP-1678 is an authoritarian parallel London located underground that suggests certain doom to those above that don''t join their salvation.","summaryBullets":["Tyranny! forces players to start picking up the pace and get executions going, preventing in-activity.","When night falls, if nobody was executed today, all players play Klutz-Fallacy using a coin-flip, where the good team will gain information on who the Demon is/isn''t, or lose on the spot.","When the Tyranny! activates, all players must publicly choose a coin side - heads or tails. Players are not allowed to make their choice privately.","After all players have made their decision, the Storyteller flips a coin and publicly reveals the result once it lands.","If the Demon''s choice is the side the Storyteller''s coin landed on, the evil team wins the game immediately."],"howToRun":["Each dusk, if no player was executed today, **the Tyranny! activates** - declare that all players must publicly choose a coin side. Note the decision the Demon makes with either the **HEADS** or **TAILS** reminder token marked by their character token. After getting all players'' choices, obtain a coin and flip it. If the Demon''s coin side guess is correct, the game ends and the evil team wins. Otherwise, the game continues. As with all Fableds, remember that this bypasses all mis-registration effects. If there are multiple Demons but only 1 alive {{i|(or just active)}} one, count that Demon only. If there are multiple Demons that are alive/active, all Demons must have their coin side correct for the evil team to win."],"tips":["Feel free to purposely exclude players from needing to make a decision depending on the on-script characters, such as excluding dead players if there is no possible way an active Demon can be dead and the game still continues {{i|(Ex. Zombuul)}}.","When playing online, where the visibility of the coin flip''s outcome is likely invisible to other players, play honestly and genuinely flip a coin or use a coin-flipping website to determine the outcome, otherwise you impose no actual teeth or threat using this fabled to encourage executions.","**Optional rule:** You may also choose to adjust the rules of this Fabled if good''s goal to execute the Demon has been altered, such as the Lleech winning if their host''s coin flip is correct as opposed to them.","**Optional rule:** you may allow for players not to make a decision at all with what coin side they choose, which only affects the Demon and if they''ll win or not. However, this goes against the original intent of the Tyranny!, and is not recommended unless you know what you are doing."],"iconBy":"le_nuberto","firstNight":0,"otherNight":0,"reminders":["Heads","Tails"],"setup":false,"art":"art/tyranny.png","jsonId":"tyranny_scp_fragmented_veil","curata":false}','scp-fragmented-veil/tyranny','published',datetime('now'),datetime('now')),
('the-gift','The Gift','fabled','legitch',NULL,'','SCP Fragmented Veil','{"slug":"the-gift","name":"The Gift","team":"fabled","ability":"Players experiencing any hardships (in-game or in real life) might have something good happen to them or their ability.","creator":"legitch","appearsIn":"SCP Fragmented Veil","lede":"SCP-2536 is the gift that keeps on giving - pity {{i|(LOSER)}}.","summaryBullets":["At any time, the Storyteller may do anything good to a player as a catch-up mechanic, or to help improve the general mood of the game.","The Gift''s effect can do anything, which includes being silent about it''s effects, telling just the effected player, or even telling every player publicly.","The Storyteller may also consider the player''s emotions or state of affairs in regards to whether they should trigger this for them."],"howToRun":["At any time, if you notice that a player is not performing to well within the game, you may choose to do **something good for them or their ability**. You may need to mark their character token with a **SOMETHING X** reminder, to remind that they are now sober & healthy, or they may use their ability twice, or they have double the votes and potential to nominate, or simply as a reminder to decide on what to do later."],"tips":["It''s best recommended to only add this Fabled to your casual games in known groups."],"iconBy":"le_nuberto","firstNight":0,"otherNight":0,"reminders":["Something ok","Something good","Something great!","Something excellent!!","Something terrific!!!"],"setup":false,"art":"art/the-gift.png","jsonId":"thegift_scp_fragmented_veil","curata":false}','scp-fragmented-veil/the-gift','published',datetime('now'),datetime('now')),
('dr-maynard','Dr. Maynard','fabled','legitch',NULL,'','SCP Fragmented Veil','{"slug":"dr-maynard","name":"Dr. Maynard","team":"fabled","ability":"Before setup, the player designated to be Demon gets the choice of Demons they get to be.","creator":"legitch","appearsIn":"SCP Fragmented Veil","lede":"Dr. Maynard is a traitor to the foundation that enables all hell to be broken loose.","summaryBullets":["At the start of the game, a player is chosen to be the Demon, and gets a list of Demons they can choose on being.","This list may be between at-least 2 Demons to all Demons present on the script.","Any setup effects imposed by the Demon chosen will also be applied as normal."],"howToRun":["At the start of the game, declare that Dr. Maynard is in play. Add the Dr. Maynard token to the Grimoire.","Before setting up the game, choose the player that will be the Demon, mark them with the **DEMON** reminder, and wake them. Show them the Demon character tokens they can choose. The Demon player points to a Demon character icon on their character sheet. **That player is the Demon they chose** - set them up with the new Demon character token on Grimoire and put a Townsfolk in the character bag instead of the Demon token. Adjust for any setup effects the Demon has. Put the Demon player to sleep.","When sending out character tokens, when you reach the Demon player, take out a Townsfolk token instead - they already have their character token."],"tips":["If the method of communication to the Demon is not reliable in doing silently and could compromise their identity, feel free to choose another method to achieve the same effect, such as silently texting the player or talking to them before the game even begins."],"iconBy":"le_nuberto","firstNight":0,"otherNight":0,"reminders":["Demon"],"setup":true,"art":"art/dr-maynard.png","jsonId":"drmaynard_scp_fragmented_veil","curata":false}','scp-fragmented-veil/dr-maynard','published',datetime('now'),datetime('now')),
('w-s-library','W''s Library','fabled','legitch',NULL,'','SCP Fragmented Veil','{"slug":"w-s-library","name":"W''s Library","team":"fabled","ability":"Successful kills after the 1st each night instead poison the victim from now on. Day kills are delayed until night.","creator":"legitch","appearsIn":"SCP Fragmented Veil","lede":"The Wanderer''s Library is a safehaven of books that prevents there being more than 1 recognizable kill.","summaryBullets":["Each night, only the 1st kill on a player will cause them to die - further kills made that night instead indefinitely poison them from now on.","Kills prevented by any protection effect don''t register for this Fabled, neither as the 1st kill, or any subsequent ones that would poison instead.","Players poisoned by this Fabled will continue to be poisoned, even if the killer is dead or they gain a healthiness effect.","However, players affected whilst currently healthy will remain unpoisoned until they are vulnerable for any amount of time afterwards.","If a player would die during the day due to another player''s ability, that death is delayed until after any possible Demon or Minion kills."],"howToRun":["If any player would die tonight but there is a **DEAD** reminder present on another player, that player is instead **poisoned** - mark them with the **POISONED** reminder, unless that player''s ability makes them permanently healthy without any conditions {{i|(if a player is made temporarily healthy by an ability, still mark them with the reminder, but don''t treat them as permanently-poisoned until they lose that healthiness)}}.","If any player would die to any player''s ability during the day, they remain alive. Mark their character token with the **DEAD** reminder token. Tonight, the player marked with this **DEAD** reminder **dies** {{i|(or is **poisoned** depending on circumstances)}}."],"iconBy":"le_nuberto","firstNight":0,"otherNight":51.114,"reminders":["Poisoned","Poisoned","Poisoned","Poisoned","Dead","Dead"],"setup":false,"otherNightReminder":"If a day kill was delayed: those marked with ''Dead'' die or are poisoned if another player is dieing tonight.","art":"art/w-s-library.png","jsonId":"wslibrary_scp_fragmented_veil","curata":false}','scp-fragmented-veil/w-s-library','published',datetime('now'),datetime('now'));
